import{z as i,x as d,o as E,c as n,q as A,j as t,D as e,d as r,s,S as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"裸机启动","description":"","frontmatter":{"title":"裸机启动","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-bare-metal-boot.md","filePath":"cs/emb-bare-metal-boot.md","lastUpdated":1791413859000}'),c={name:"cs/emb-bare-metal-boot.md"};function l(p,a,m,C,D,M){const o=d("Mermaid");return E(),n("div",null,[a[2]||(a[2]=A('<h1 id="裸机启动" tabindex="-1">裸机启动 <a class="header-anchor" href="#裸机启动" aria-label="Permalink to &quot;裸机启动&quot;">​</a></h1><div class="epigraph"><p>复位释放的那一刻，处理器只知道一件事：到固定的地址取第一条指令。其余的一切——栈、已初始化的全局量、清零的内存——都是启动代码在进入 main 之前替你补上的约定。</p><footer>—— 据 ARMv7-M Architecture Reference Manual；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/orch-case-map">上一课</a>给「容器编排」收束：声明、循环、预算三件套贯穿全课程，判据三问——这负载吃哪些机制的重、哪些是纯税、不满足时错在哪层——把四个案例各归其位；编排不解决安全边界、可观测性与容量规划，越界的期待都会变成事故。编排的栈再高，底下仍是通用计算机的台子：主干课的<a href="/cs/bios-uefi">固件：BIOS 与 UEFI</a>讲过，上电之后 BIOS/UEFI 先训练 DRAM、枚举设备，再把内核装进内存，软件从头到尾站在固件搭好的台子上。本课是「嵌入式系统」的第一课，问的正是这个台子被抽掉之后还剩什么：在一颗微控制器上，没有另一个程序先你而启动，复位向量指向的代码就是你自己写的。后课的中断、外设、RTOS 与功耗，都默认你已经能让 main 跑起来，不再从「上电发生了什么」讲起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上电复位只保证处理器状态确定：寄存器清零、PC 装入复位向量。C 程序却预设了一整套运行时约定：函数调用要有栈指针，未初始化的全局量读出来是零，带初值的全局量一上电就是那个初值。固件不在场时，这些约定没有人为你兑现。缺口因此不是「写个 main」，而是<strong>复位到 main 之间那段没有名字的代码</strong>：栈从哪里拿、<code>.data</code> 从哪里搬到哪里、<code>.bss</code> 由谁清零。任何一步缺席，程序不是编译不过，而是在板上以更糟的方式失败——栈没设就调 C 函数，第一次压栈就写进未知内存。</p><p><span class="marginnote">常见误区：以为写完 main 就万事俱备。桌面程序上电前有 BIOS/UEFI 和内核替你把栈、全局量、堆安排妥当；裸机上没人代劳——复位后第一秒的世界里只有你的启动代码和一张向量表，所有「语言约定」都要从零亲手兑现。</span></p><h3 id="链接脚本决定一切的位置" tabindex="-1">链接脚本决定一切的位置 <a class="header-anchor" href="#链接脚本决定一切的位置" aria-label="Permalink to &quot;链接脚本决定一切的位置&quot;">​</a></h3><p>启动的前提是<strong>地址空间布局</strong>先被声明：哪段是闪存、哪段是 SRAM、各多大、起于哪个地址。这延续了<a href="/cs/bus-mmio">总线与 MMIO</a> 的译码视角——CPU 发出的地址由各从设备认领，只是对象换成了片上存储。链接脚本的 <code>MEMORY</code> 与 <code>SECTIONS</code> 把每个段钉到具体地址；钉错了，代码下载到不存在的地址，处理器从向量表取到的第一条指令就是总线错误。</p><p><span class="marginnote">数字实例：Cortex-M 复位时，硬件从地址 0x0000_0000 取第 0 个字装进主栈指针 SP，取第 1 个字装进 PC 作复位处理函数——向量表头两项是纯硬件行为。表放错位置，PC 装进的就是垃圾值，第一条「指令」都不知道是什么。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动代码（习惯叫 crt0 或 startup 文件）按固定次序做四件事。第一，从向量表取出初始栈指针装入 SP——在 Cortex-M 上，向量表第 0 个字就是主栈指针初值，第 1 个字才是复位处理函数地址，硬件复位时自动装载这两项。第二，把 <code>.data</code> 从它在闪存里的装载地址（LMA）复制到运行地址（VMA）：初值必须烧进掉电不丢的闪存，但变量必须住在可写的 SRAM，两个地址由链接脚本分别指定。第三，把 <code>.bss</code> 区间整段清零，兑现「未初始化即零」的语言约定。第四，调用 main。次序不可换：SP 必须最先，否则任何函数调用都是踩空；<code>.bss</code> 清零必须在 main 之前，否则全局状态从垃圾值起跑。</p>',11)),(E(),t(B,null,{default:e(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RST%5B%22%E5%A4%8D%E4%BD%8D%E9%87%8A%E6%94%BE%EF%BC%9APC%20%E8%A3%85%E5%85%A5%E5%A4%8D%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%20--%3E%20SPV%5B%22%E7%A1%AC%E4%BB%B6%E8%A3%85%E8%BD%BD%E5%88%9D%E5%A7%8B%20SP%20%E4%B8%8E%E5%A4%8D%E4%BD%8D%E5%87%BD%E6%95%B0%22%5D%0A%20%20SPV%20--%3E%20CPY%5B%22%E6%8C%89%20LMA%20%E5%88%B0%20VMA%20%E5%A4%8D%E5%88%B6%20.data%22%5D%0A%20%20CPY%20--%3E%20ZRO%5B%22%E6%B8%85%E9%9B%B6%20.bss%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20ZRO%20--%3E%20MAIN%5B%22%E8%B0%83%E7%94%A8%20main%EF%BC%9AC%20%E8%BF%90%E8%A1%8C%E6%97%B6%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20MAIN%20--%3E%20LOOP%5B%22%E4%B8%BB%E5%BE%AA%E7%8E%AF%E6%88%96%E8%B0%83%E5%BA%A6%E5%99%A8%E6%8E%A5%E7%AE%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p><span class="marginnote">一颗典型 MCU 的账：64 KB 闪存映射在 0x0800_0000，20 KB SRAM 映射在 0x2000_0000，向量表占闪存开头几百字节。<code>.data</code> 段 200 字节，启动时就要从闪存复制 200 字节到 SRAM——LMA 与 VMA 分离正是为此。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么必须区分 LMA 与 VMA？因为「存放在哪」和「在哪儿被访问」是两个约束：闪存掉电不丢但不可就地改写，SRAM 可写但掉电即失。链接器允许一段有两个地址，把「搬运」留给启动代码，这是软件与存储介质特性的和解。同理，<code>.bss</code> 不占镜像空间——清零段只需记起点和长度，省下的闪存正是一名嵌入式工程师盯得最紧的预算。</p><p><span class="marginnote">直觉类比：LMA 像家具在仓库里的存放位，VMA 是它在房间里的使用位——桌子不能一直住在快递箱里。<code>.data</code> 的初值「存」在闪存、「用」在 SRAM，启动代码就是那段搬家动作；<code>.bss</code> 连箱子都不用，搬进去时统一发一套空的。</span></p><p>同一份全局数据，为什么在闪存和 SRAM 里各有一个地址？</p>',5)),(E(),t(B,null,{default:e(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20FL%5B%22%E9%97%AA%E5%AD%98%EF%BC%9A%E6%8E%89%E7%94%B5%E4%B8%8D%E4%B8%A2%EF%BC%8C%E4%B8%8D%E5%8F%AF%E5%B0%B1%E5%9C%B0%E6%94%B9%E5%86%99%22%5D%0A%20%20%20%20LMA%5B%22data%20%E6%AE%B5%E8%A3%85%E8%BD%BD%E5%9C%B0%E5%9D%80%20LMA%EF%BC%9A%E5%88%9D%E5%80%BC%E7%83%A7%E5%9C%A8%E8%BF%99%E9%87%8C%22%5D%0A%20%20%20%20VEC%5B%22%E5%90%91%E9%87%8F%E8%A1%A8%E4%B8%8E%E4%BB%A3%E7%A0%81%E9%95%9C%E5%83%8F%22%5D%0A%20%20end%0A%20%20subgraph%20SR%5B%22SRAM%EF%BC%9A%E5%8F%AF%E5%86%99%EF%BC%8C%E6%8E%89%E7%94%B5%E5%8D%B3%E5%A4%B1%22%5D%0A%20%20%20%20VMA%5B%22data%20%E6%AE%B5%E8%BF%90%E8%A1%8C%E5%9C%B0%E5%9D%80%20VMA%EF%BC%9A%E5%8F%98%E9%87%8F%E4%BD%8F%E5%9C%A8%E8%BF%99%E9%87%8C%22%5D%0A%20%20%20%20BSS%5B%22bss%20%E5%8C%BA%E9%97%B4%EF%BC%9A%E4%B8%8D%E5%8D%A0%E9%95%9C%E5%83%8F%EF%BC%8C%E4%B8%8A%E7%94%B5%E5%90%8E%E6%B8%85%E9%9B%B6%22%5D%0A%20%20end%0A%20%20LMA%20--%3E%7C%22%E5%90%AF%E5%8A%A8%E4%BB%A3%E7%A0%81%E6%8C%89%E5%AD%97%E5%A4%8D%E5%88%B6%22%7C%20VMA%0A%20%20ZRO%5B%22%E5%90%AF%E5%8A%A8%E4%BB%A3%E7%A0%81%E6%95%B4%E6%AE%B5%E5%86%99%E9%9B%B6%22%5D%20--%3E%20BSS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p>为什么向量表必须在固定偏移？复位逻辑是纯硬件状态机，它不读文件系统也不解析格式，只按芯片手册钉死的地址取头两项。芯片的 ROM 引导加载器能从 UART 或 USB 把镜像搬进闪存，调试器下载看似绕过这一套，但复位一次，该走的路径一步不少。后课的中断实践正是接在向量表上：表里除复位项外，其余每项都是一类异常或中断的入口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只写微控制器的裸机启动，不写应用处理器：DRAM 训练、多核拉起、安全启动度量是<a href="/cs/secure-boot-chain">固件与安全启动链</a>那一层的工程，与几百字节的 crt0 不是一个物种。也不写操作系统的接管——引导加载器装核、内核建页表再挂根的那条路，在<a href="/cs/early-boot">早期启动</a>讲过，本课停在 main 为止。变体只点名不展开：有的芯片要求把代码从片外闪存复制进 RAM 再执行，带缓存的核还要处理取指与数据的一致性。最后一条纪律：启动代码里禁止调用任何假设运行时就绪的库函数——printf 在 <code>.bss</code> 清零之前是未定义行为，不是「碰巧能跑」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复位只给确定状态；栈、<code>.data</code>、<code>.bss</code> 三件事是 main 之前的隐形契约。</li><li>链接脚本先声明地址布局，启动代码再兑现语言约定，次序不可换。</li><li>LMA 与 VMA 分离是闪存与 SRAM 特性互补的结果，<code>.bss</code> 清零段不占镜像。</li><li>向量表的固定偏移是硬件状态机的约定，ROM 引导与调试下载都回到它。</li><li>出处：ARMv7-M Architecture Reference Manual；Harris and Harris, <em>Digital Design and Computer Architecture</em>；据本栏 bus-mmio、bios-uefi 两课的地址译码与固件口径整理。</li></ul>',5))])}const _=i(c,[["render",l]]);export{b as __pageData,_ as default};
